const { chromium } = require('playwright');
const F='file:///private/var/folders/hf/35wnqrnj2bbb1_llbg87zlt40000gn/T/vs-b88dcfdc015f48ff/card.html';
(async()=>{
const b=await chromium.launch();
for (const [w,h,n] of [[1080,1080,'square'],[1920,1080,'landscape'],[1080,1920,'story']]){
  const p=await b.newPage({viewport:{width:w,height:h}});
  await p.goto(F); await p.waitForTimeout(400);
  const r=await p.evaluate(({w,h})=>{
    const out={overflow:[],clip:[],boxes:{},overlaps:[]};
    const sel=['.brand','.brand img','.event','.avatar','.name','.role','.title','.meta','.cta','.foot','.speaker'];
    const els=sel.map(s=>[s,document.querySelector(s)]).filter(x=>x[1]);
    for(const [s,e] of els){
      const b=e.getBoundingClientRect();
      out.boxes[s]=[Math.round(b.x),Math.round(b.y),Math.round(b.width),Math.round(b.height)];
      if(b.left<-0.5||b.top<-0.5||b.right>w+0.5||b.bottom>h+0.5) out.overflow.push([s,JSON.stringify(out.boxes[s])]);
      if(e.scrollWidth>e.clientWidth+1||e.scrollHeight>e.clientHeight+1) out.clip.push([s,e.scrollWidth,e.clientWidth,e.scrollHeight,e.clientHeight]);
    }
    const leaves=['.brand img','.event','.avatar','.name','.role','.title','.meta','.cta'].map(s=>[s,document.querySelector(s).getBoundingClientRect()]);
    for(let i=0;i<leaves.length;i++)for(let j=i+1;j<leaves.length;j++){
      const a=leaves[i][1],c=leaves[j][1];
      const ox=Math.min(a.right,c.right)-Math.max(a.left,c.left);
      const oy=Math.min(a.bottom,c.bottom)-Math.max(a.top,c.top);
      if(ox>1&&oy>1) out.overlaps.push([leaves[i][0],leaves[j][0],Math.round(ox),Math.round(oy)]);
    }
    const t=document.querySelector('.title');
    out.titleLines=Math.round(t.getBoundingClientRect().height/parseFloat(getComputedStyle(t).lineHeight));
    out.docScroll=[document.documentElement.scrollWidth,document.documentElement.scrollHeight];
    out.font=getComputedStyle(t).fontFamily;
    out.fontLoaded=document.fonts.check('700 62px Inter');
    return out;
  },{w,h});
  console.log('===',n,JSON.stringify(r,null,1));
  await p.close();
}
await b.close();})();
